WITH scored AS (SELECT id, session_id, page, event_time, SUM(duration_sec) OVER w_part AS running_sum_duration_sec, MIN(duration_sec) OVER w_part AS running_min_duration_sec, COUNT(duration_sec) OVER w_part AS running_count_duration_sec FROM web_events WINDOW w_part AS (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), deduped AS (SELECT * FROM scored QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY running_count_duration_sec, id) = 1), joined AS (SELECT e.id, e.session_id, e.page, e.running_sum_duration_sec, e.running_count_duration_sec, s.device, s.browser, s.country FROM deduped e LEFT JOIN sessions s ON e.session_id = s.id), enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY running_sum_duration_sec, id) AS event_seq, MIN(running_count_duration_sec) OVER (PARTITION BY page) AS page_min_running_count_duration_sec, NTILE(3) OVER (PARTITION BY page, country ORDER BY running_sum_duration_sec, id) AS running_sum_duration_sec_bucket, SUM(running_sum_duration_sec) OVER (PARTITION BY page, session_id ORDER BY running_sum_duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_running_sum_duration_sec, RANK() OVER (PARTITION BY session_id ORDER BY running_count_duration_sec DESC) AS running_count_duration_sec_rank FROM joined WHERE running_sum_duration_sec IS NOT NULL), filtered AS (SELECT id, page, browser, country, page_min_running_count_duration_sec, running_sum_duration_sec_bucket, running_running_sum_duration_sec, running_count_duration_sec_rank, ROUND(page_min_running_count_duration_sec, 2) AS page_min_running_count_duration_sec_rounded, GREATEST(page_min_running_count_duration_sec, running_count_duration_sec) AS greatest_page_min_running_count_duration_sec_running_count_duration_sec FROM enriched WHERE running_count_duration_sec_rank >= 4) SELECT id, browser, country, page_min_running_count_duration_sec, running_running_sum_duration_sec, page_min_running_count_duration_sec_rounded, greatest_page_min_running_count_duration_sec_running_count_duration_sec FROM filtered
